class Solution:
    def minimumRecolors(self, blocks: str, k: int) -> int:
        whites = blocks[:k].count('W')          # first window
        best = whites
        for r in range(k, len(blocks)):         # slide one block at a time: O(n)
            whites += blocks[r] == 'W'          # block entering
            whites -= blocks[r - k] == 'W'      # block leaving
            best = min(best, whites)
        return best

